   subroutine get_cartesian_ao_g0(block_length, &
                                  l,            &
                                  px,           &
                                  py,           &
                                  pz,           &
                                  ao)

!     --------------------------------------------------------------------------
      integer, intent(in)  :: block_length
      integer, intent(in)  :: l
      real(8), intent(in)  :: px(*)
      real(8), intent(in)  :: py(*)
      real(8), intent(in)  :: pz(*)
