              ao(k, 24) = py(k)*g_00_03_02_000(k)
              ao(k, 25) = py(k)*g_00_02_03_000(k)
              ao(k, 26) = py(k)*g_00_01_04_000(k)
              ao(k, 27) = py(k)*g_00_00_05_000(k)
