   end subroutine

   subroutine get_cartesian_ao_g1(block_length, &
                                  l,            &
                                  px,           &
                                  py,           &
                                  pz,           &
                                  ao,           &
                                  ao_x,         &
                                  ao_y,         &
                                  ao_z)

!     --------------------------------------------------------------------------
      integer, intent(in)  :: block_length
      integer, intent(in)  :: l
      real(8), intent(in)  :: px(*)
      real(8), intent(in)  :: py(*)
      real(8), intent(in)  :: pz(*)
      real(8), intent(out) ::   ao(mxbllen, *)
      real(8), intent(out) :: ao_x(mxbllen, *)
      real(8), intent(out) :: ao_y(mxbllen, *)
      real(8), intent(out) :: ao_z(mxbllen, *)
!     --------------------------------------------------------------------------
      integer              :: k
!     --------------------------------------------------------------------------

      if (l == 1) then
         do k = 1, block_length
              ao(k, 01) = g_00_00_00_000(k)
            ao_x(k, 01) = g_00_00_00_100(k)
            ao_y(k, 01) = g_00_00_00_010(k)
            ao_z(k, 01) = g_00_00_00_001(k)
         end do
         return
      end if

      if (l == 2) then
         do k = 1, block_length
              ao(k, 01) = px(k)*g_00_00_00_000(k)
              ao(k, 02) = py(k)*g_00_00_00_000(k)
              ao(k, 03) = pz(k)*g_00_00_00_000(k)
            ao_x(k, 01) = px(k)*g_00_00_00_100(k) + g_00_00_00_000(k)
            ao_x(k, 02) = py(k)*g_00_00_00_100(k)
            ao_x(k, 03) = pz(k)*g_00_00_00_100(k)
            ao_y(k, 01) = px(k)*g_00_00_00_010(k)
            ao_y(k, 02) = py(k)*g_00_00_00_010(k) + g_00_00_00_000(k)
            ao_y(k, 03) = pz(k)*g_00_00_00_010(k)
            ao_z(k, 01) = px(k)*g_00_00_00_001(k)
            ao_z(k, 02) = py(k)*g_00_00_00_001(k)
            ao_z(k, 03) = pz(k)*g_00_00_00_001(k) + g_00_00_00_000(k)
         end do
         return
      else
         do k = 1, block_length
            g_01_00_00_000(k) = px(k)*g_00_00_00_000(k)
            g_00_01_00_000(k) = py(k)*g_00_00_00_000(k)
            g_00_00_01_000(k) = pz(k)*g_00_00_00_000(k)
