            g_00_01_00_010(k) = py(k)*g_00_00_00_010(k) + g_00_00_00_000(k)
            g_00_00_01_010(k) = pz(k)*g_00_00_00_010(k)
            g_01_00_00_001(k) = px(k)*g_00_00_00_001(k)
            g_00_01_00_001(k) = py(k)*g_00_00_00_001(k)
            g_00_00_01_001(k) = pz(k)*g_00_00_00_001(k) + g_00_00_00_000(k)
         end do
      end if

      if (l == 3) then
         do k = 1, block_length
              ao(k, 01) = px(k)*g_01_00_00_000(k)
