            ao_x(k, 05) = py(k)*g_00_00_01_100(k)
            ao_x(k, 06) = pz(k)*g_00_00_01_100(k)
            ao_y(k, 01) = px(k)*g_01_00_00_010(k)
            ao_y(k, 02) = px(k)*g_00_01_00_010(k)
            ao_y(k, 03) = px(k)*g_00_00_01_010(k)
            ao_y(k, 04) = py(k)*g_00_01_00_010(k) + g_00_01_00_000(k)
            ao_y(k, 05) = py(k)*g_00_00_01_010(k) + g_00_00_01_000(k)
            ao_y(k, 06) = pz(k)*g_00_00_01_010(k)
            ao_z(k, 01) = px(k)*g_01_00_00_001(k)
