         end do
         return
      else
         do k = 1, block_length
            g_02_00_00_000(k) = px(k)*g_01_00_00_000(k)
            g_01_01_00_000(k) = px(k)*g_00_01_00_000(k)
            g_01_00_01_000(k) = px(k)*g_00_00_01_000(k)
            g_00_02_00_000(k) = py(k)*g_00_01_00_000(k)
            g_00_01_01_000(k) = py(k)*g_00_00_01_000(k)
            g_00_00_02_000(k) = pz(k)*g_00_00_01_000(k)
            g_02_00_00_100(k) = px(k)*g_01_00_00_100(k) + g_01_00_00_000(k)
            g_01_01_00_100(k) = px(k)*g_00_01_00_100(k) + g_00_01_00_000(k)
            g_01_00_01_100(k) = px(k)*g_00_00_01_100(k) + g_00_00_01_000(k)
            g_00_02_00_100(k) = py(k)*g_00_01_00_100(k)
            g_00_01_01_100(k) = py(k)*g_00_00_01_100(k)
            g_00_00_02_100(k) = pz(k)*g_00_00_01_100(k)
