            ao_y(k, 04) = px(k)*g_00_02_00_010(k)
            ao_y(k, 05) = px(k)*g_00_01_01_010(k)
            ao_y(k, 06) = px(k)*g_00_00_02_010(k)
            ao_y(k, 07) = py(k)*g_00_02_00_010(k) + g_00_02_00_000(k)
            ao_y(k, 08) = py(k)*g_00_01_01_010(k) + g_00_01_01_000(k)
            ao_y(k, 09) = py(k)*g_00_00_02_010(k) + g_00_00_02_000(k)
            ao_y(k, 10) = pz(k)*g_00_00_02_010(k)
            ao_z(k, 01) = px(k)*g_02_00_00_001(k)
