            g_00_00_03_000(k) = pz(k)*g_00_00_02_000(k)
            g_03_00_00_100(k) = px(k)*g_02_00_00_100(k) + g_02_00_00_000(k)
            g_02_01_00_100(k) = px(k)*g_01_01_00_100(k) + g_01_01_00_000(k)
            g_02_00_01_100(k) = px(k)*g_01_00_01_100(k) + g_01_00_01_000(k)
